<h1><?= e(t('Family board')) ?></h1><p><?= e(t('Shared chores between linked profiles. Private records remain in their own workspaces.')) ?></p><a href="/profiles"><?= e(t('Profiles & consent')) ?></a>
<?php if(!ProfileManager::isKid()): ?><section class="card"><form class="stack" method="post" action="/family"><?= csrf_field() ?><label><?= e(t('Child')) ?><select name="child" required><?php foreach(ProfileManager::children()as $child): ?><option value="<?= e($child['id']) ?>"><?= e($child['name']) ?></option><?php endforeach; ?></select></label><label><?= e(t('Chore')) ?><input name="title" maxlength="200" required></label><label><?= e(t('Due')) ?><input type="date" name="due" required></label><label><?= e(t('Your guardian PIN')) ?><input type="password" name="pin" required></label><button><?= e(t('Assign shared chore')) ?></button></form><?php foreach(ProfileManager::children()as $child): ?><p><a href="/profiles/child/<?= e($child['id']) ?>/school"><?= e($child['name']) ?> <?= e(t('· Weekly school report')) ?></a></p><?php endforeach; ?></section><?php endif; ?>
<section class="card"><?php if(!$items): ?><p><?= e(t('No shared chores.')) ?></p><?php endif; ?><?php foreach($items as $item): ?><article><h2><?= e($item['title']) ?></h2><p><?= e($item['child_name']) ?> · <?= e($item['due']) ?> · <?= $item['done']?t('Complete'):t('Open') ?></p><?php if(!$item['done']): ?><form method="post" action="/family/<?= e($item['id']) ?>/done"><?= csrf_field() ?><button><?= e(t('Complete')) ?></button></form><?php endif; ?></article><?php endforeach; ?></section>
